AS
   declare variable ordernum integer; 
   declare variable rsult integer;
BEGIN 
    /* if the order is no longer on any equipment, reset its status (remove the ASG status) */ 
    if (COALESCE(OLD.DPD_LOAD_NUMBER,0) = 0) then 
        exit;
        
    if (not exists(select DPD_LOAD_NUMBER FROM DRIVER_PKUP_DELV 
                   WHERE DPD_LOAD_NUMBER = OLD.DPD_LOAD_NUMBER)) THEN
    BEGIN
       ordernum = old.dpd_load_number;
       execute procedure SET_ORDER_HDR_STATUS :ordernum returning_values :rsult;
    END

END

