AS
declare variable LAT double precision;
declare variable LON double precision;
declare variable NS varchar(1);
declare variable EW varchar(1);
declare variable LCITY varchar(35);
declare variable LSTATE varchar(2);
begin
    if ((COALESCE(OLD.ES_STATUS, 0) <> COALESCE(NEW.ES_STATUS, 0)) OR
        (COALESCE(OLD.ES_LOC_TYPE, ' ') <> COALESCE(NEW.ES_LOC_TYPE, ' ')) OR
        (COALESCE(OLD.ES_LOCATION, ' ') <> COALESCE(NEW.ES_LOCATION, ' ')) OR
        (COALESCE(OLD.ES_ASG_DRIVER, 0) <> COALESCE(NEW.ES_ASG_DRIVER, 0)) OR
        (COALESCE(OLD.ES_ASG_DRIVER2, 0) <> COALESCE(NEW.ES_ASG_DRIVER2, 0)) OR
        (COALESCE(OLD.ES_ASG_TRACTOR, 0) <> COALESCE(NEW.ES_ASG_TRACTOR, 0)) OR
        (COALESCE(OLD.ES_ASG_TRAILER, 0) <> COALESCE(NEW.ES_ASG_TRAILER, 0)) OR
        (COALESCE(OLD.ES_NUM_SHIPMENTS, 0) <> COALESCE(NEW.ES_NUM_SHIPMENTS, 0)) OR
        (COALESCE(OLD.ES_MANIFEST_NUMBER, 0) <> COALESCE(NEW.ES_MANIFEST_NUMBER, 0)) OR
        (COALESCE(OLD.ES_STOP_ID,  0) <> COALESCE(NEW.ES_STOP_ID, 0))) then
    begin
        NEW.ES_COMMENT = NEW.ES_COMMENT||' .';
        INSERT INTO EQUIP_HISTORY
          (EH_ID, EH_SEQUENCE, EH_TIME, EH_INITIALS, EH_STATUS, EH_STATUS_TIME,
           EH_LOC_TYPE, EH_LOCATION, EH_ASG_DRIVER, EH_STOP_ID, EH_ASG_TRACTOR, EH_ASG_TRAILER,
           EH_ASG_DRIVER2, EH_NUM_SHIPMENTS, EH_PRIOR_STATUS, EH_MANIFEST_NUMBER,
           EH_COMMENT)
          VALUES
          (NEW.ES_ID, GEN_ID(HIST_GEN, 1), CAST('NOW' AS TIMESTAMP),
           NEW.ES_INITIALS, NEW.ES_STATUS, NEW.ES_STATUS_DATE, NEW.ES_LOC_TYPE,
           NEW.ES_LOCATION, NEW.ES_ASG_DRIVER, NEW.ES_STOP_ID,
           NEW.ES_ASG_TRACTOR, NEW.ES_ASG_TRAILER, NEW.ES_ASG_DRIVER2, NEW.ES_NUM_SHIPMENTS,
           OLD.ES_STATUS, NEW.ES_MANIFEST_NUMBER, NEW.ES_COMMENT);
    end
    
    select LAT, LON, LCITY, LSTATE FROM EQUIP_STATUS
       LEFT JOIN LOCATION_LAT_LON(NEW.ES_LOC_TYPE, NEW.ES_LOCATION) ON 1 = 1
       LEFT JOIN LOCATION_DETAIL(NEW.ES_LOC_TYPE, NEW.ES_LOCATION) ON 1= 1
    WHERE ES_ID = NEW.ES_ID
    INTO :LAT, :LON, :LCITY, :LSTATE;

    if (LAT <> 0) THEN
    BEGIN
        /* Convert from +/- coordinates to N/S, E/W coordinates */
        if (LAT < 0) then
        begin
            NS = 'S';
            LAT = -LAT;
        end else
        begin
            NS = 'N';
        end
        if (LON < 0) then
        begin
            EW = 'W';
            LON = -LON;
        end else
        begin
            EW = 'E';
        end
       new.es_pos_date = cast('NOW' AS TIMESTAMP);
       NEW.ES_POS_LATITUDE = LAT;
       NEW.ES_POS_LONGITUDE = LON;
       NEW.ES_POS_EW = EW;
       NEW.ES_POS_NS = NS;  
       NEW.ES_POS_CITY = LCITY;
       NEW.ES_POS_STATE = LSTATE;    
    end 
    /* Clear these fields so that they will not propogate from one
       status change to the next. */
    NEW.ES_MANIFEST_NUMBER = NULL;
    NEW.ES_STOP_ID = NULL;
    NEW.ES_INITIALS = NULL;
    NEW.ES_COMMENT = NULL;
end

