AS
begin
    /* Do not delete OPS_HISTORY records here! We want to be able to
       retain order history as the order is modified by EDI transactions.
       Since the EDI modify transaction deletes the order and re-creates
       it we can't delete the history when the order is deleted. */
    DELETE FROM OPS_AGENTS
      WHERE OPA_ORDER_ID = OLD.PB_ID;
    DELETE FROM OPS_EDI_HISTORY
      WHERE OPEH_ORDER_ID = OLD.PB_ID;
    DELETE FROM OPS_LINE_ITEMS
      WHERE OPL_ORDER_ID = OLD.PB_ID;
    DELETE FROM OPS_NUMBERS
      WHERE OPN_ORDER_ID = OLD.PB_ID;
    DELETE FROM OPS_STOP_REC
      WHERE OPS_ORDER_ID = OLD.PB_ID;
    DELETE FROM DRIVER_PKUP_DELV
      WHERE DPD_LOAD_NUMBER = OLD.PB_ID;
    DELETE FROM OPS_MFST_INFO
      WHERE OMI_MFST_ID = OLD.PB_ID;
end

