AS
declare variable ordernum integer;
declare variable rsult integer; 
BEGIN 
	/* enter trigger code here */ 
	if ((old.ops_status <> new.ops_status)
	                  or
       (old.ops_status_time <> new.ops_status_time)) THEN
       BEGIN
         ordernum = new.ops_order_id;
         execute procedure SET_ORDER_HDR_STATUS :ordernum returning_values :rsult; 
       end
END

